def build():
    total = {}
    for key, items in Q.items():
        name, source, pre = SUBJ[key]
        out = []
        for i, (q, opts, ans, expl, diff, keyq) in enumerate(items, 1):
            assert len(opts) == 4 and 0 <= ans < 4
            out.append({"id": f"{pre}-{i:02d}", "subject": key, "subjectName": name, "source": source,
                        "question": q, "options": opts, "answer": ans, "explanation": expl,
                        "difficulty": diff, "key": keyq, "approved": True})
        os.makedirs(f"data/{key}", exist_ok=True)
        with open(f"data/{key}/preguntas.json", "w", encoding="utf-8") as f:
            json.dump(out, f, ensure_ascii=False, indent=2)
        longest = sum(1 for (_, o, a, *_ ) in items if len(o[a]) == max(map(len, o)) and sorted(map(len, o))[-2] < len(o[a]))
        pos = [a for (_, _, a, *_) in items]
        total[key] = (len(items), longest, {p: pos.count(p) for p in range(4)})
    for k, v in total.items():
        print(f"{k:12s} preguntas={v[0]:2d}  correcta_estrictamente_más_larga={v[1]:2d}  posiciones={v[2]}")

if __name__ == "__main__":
    build()
